local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local cs_coroutine = require 'XLua.cs_coroutine'
local KCookie = CS.Engine.Lib.KCookie
local GuideUtils = import('Game.UI.Guide.GuideUtils')
local LoopListViewInitParam = CS.SuperScrollView.LoopListViewInitParam
local ItemCornerEnum = CS.SuperScrollView.ItemCornerEnum

