---@class HomeScrollNode
---@field controller                        Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field AdvertScrollView                SuperScrollView.LoopListView2
---@field ImgPoint                        UnityEngine.RectTransform
---@field PageGroup                        UnityEngine.RectTransform
local HomeScrollNode = Class('HomeScrollNode')

function HomeScrollNode:__init()
    self._allData = {}
    self.curIndex = 1
    self.dots = nil
end

function HomeScrollNode:__delete()
    self._allData = nil
    self.curIndex = -1
    self.dots = nil
end

function HomeScrollNode:Awake()
    self:InitData()
end

function HomeScrollNode:Start()
    self:InitialDots()
    ---@type SuperScrollView.LoopListViewInitParam
    local initParam = LoopListViewInitParam.CopyDefaultInitParam()
    initParam.mSnapVecThreshold = 99999
    self.AdvertScrollView.mOnEndDragAction = function()
        local vec = self.AdvertScrollView.ScrollRect.velocity.x
        local curNearestItemIndex = self.AdvertScrollView.CurSnapNearestItemIndex
        local item = self.AdvertScrollView:GetShownItemByItemIndex(curNearestItemIndex)
        if item == nil then
            self.AdvertScrollView:ClearSnapData();
            return
        end
        if Mathf.Abs(vec) < 50 then
            self.AdvertScrollView:SetSnapTargetItemIndex(curNearestItemIndex)
            return
        end
        local pos = self.AdvertScrollView:GetItemCornerPosInViewPort(item, ItemCornerEnum.LeftTop)
        if pos.x > 0 then
            if vec > 0 then
                self.AdvertScrollView:SetSnapTargetItemIndex(curNearestItemIndex - 1)
            else
                self.AdvertScrollView:SetSnapTargetItemIndex(curNearestItemIndex)
            end
        elseif pos.x < 0 then
            if vec > 0 then
                self.AdvertScrollView:SetSnapTargetItemIndex(curNearestItemIndex)
            else
                self.AdvertScrollView:SetSnapTargetItemIndex(curNearestItemIndex + 1)
            end
        else
            if vec > 0 then
                self.AdvertScrollView:SetSnapTargetItemIndex(curNearestItemIndex - 1)
            else
                self.AdvertScrollView:SetSnapTargetItemIndex(curNearestItemIndex + 1)
            end
        end
    end
    self.AdvertScrollView.mOnSnapNearestChanged = function(listView, item)
        self:UpdateAllDots()
    end
    if not self.AdvertScrollView.IsListViewInit then
        self.AdvertScrollView:InitListView(#self._allData, Bind(self, self.OnGetItemByIndex), initParam)
    else
        GameUtils.ReloadData(self.AdvertScrollView, #self._allData)
    end
end

function HomeScrollNode:UpdateAllDots()
    local curNearestItemIndex = self.AdvertScrollView.CurSnapNearestItemIndex
    if curNearestItemIndex < 0 or curNearestItemIndex > #self._allData then
        return
    end
    if curNearestItemIndex > #self.dots then return end
    for i, dot in pairs(self.dots) do
        if i == (curNearestItemIndex + 1) then
            CfUtils.SetUISwitchImage(dot, 1)
        else
            CfUtils.SetUISwitchImage(dot, 2)
        end
    end
end

---OnGetItemByIndex
---@param listView SuperScrollView.LoopListView2
---@param pageIndex number
function HomeScrollNode:OnGetItemByIndex(listView, pageIndex)
    if pageIndex < 0 or pageIndex >= #self._allData then
        return
    end
    local cell = listView:NewListViewItem(CellName)
    local data = self._allData[pageIndex + 1]
    SetButtonAction(cell, function()
        self:OnButtonAction(data)
    end)
    if data and not string.isEmpty(data.image) then
        local urlMd5 = CfUtils.GetUrlMds(data.image)
        if urlMd5 then
            ---@type Engine.UI.WebRawImage
            local rawImage = KTool.GetOrAddComponent(cell.gameObject, typeof(CS.Engine.UI.WebRawImage))
            rawImage.Url = tostring(data.image)
            rawImage.Md5 = urlMd5
            rawImage:LoadSprite()
        end
    end
    return cell
end

function HomeScrollNode:OnButtonAction(data)
    --引导中  退出
    if GuideUtils.IsInGuiding() then
        return
    end

    --如果不在主界面  退出
    if not self._allData then
        return
    end
    if not data then
        return
    end

    -- 临时把这个按钮改成进入 梦空间场景的入口
    GameUtils.OpenLoadingPanel(
        UIArgs(Constants.UITypeIds.UIDreamSpaceLvl1SceneEnter, nil),
        {}, Constants.LoadingType.Others, false)

    if checkNumber(data.moduleId) == 0 then
        return
    end

    self:__ExecuteJump(data.moduleId, data.param)
end
---
---初始化点
function HomeScrollNode:InitialDots()
    KTool.DestroyGameObjectChildren(self.PageGroup.gameObject)
    self.dots = {}
    for i = 1, #self._allData do
        local go = KTool.Instantiate(self.PageGroup.gameObject, self.ImgPoint.gameObject, false)
        KTool.SetActive(go, true)
        if i == self.curIndex then
            CfUtils.SetUISwitchImage(go, 1)
        else
            CfUtils.SetUISwitchImage(go, 2)
        end
        table.insert(self.dots, go)
    end
end

function HomeScrollNode:OnEventMainHomeScrollActive(body)
    if not body then
        return
    end
    KTool.SetActive(self.controller.gameObject, checkBool(body.isTrue))
end

function HomeScrollNode:__ExecuteJump(moduleId, param)
    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("__ExecuteJump")
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    xTry(function()
        cs_coroutine.start(function()
            local row = goodsConfMgr:GetJumpModuleRow(moduleId)
            if row then
                cs_coroutine.yield_return(goodsConfMgr:ExecuteJump(row, {}, 0, nil, param))
            end
            blocker:RemoveCondition("__ExecuteJump")
        end)
    end, function()
        blocker:RemoveCondition("__ExecuteJump")
    end)
end

function HomeScrollNode:InitData()
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ScrollEntryComponent)
    self._allData = comp:GetData()
    --if not self._allData or table.count(self._allData) < 1 then
    --    self._allData = {
    --        {image = 'https://img.fantanggame.com/cat-phone/79510801a77803b9b5fb1a0ec000d2a2.png'}
    --    }
    --    return
    --end
    self.curIndex = 1
end

function HomeScrollNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return HomeScrollNode